await (async page => {
  const results=[];
  for(const width of [1440,360]) {
   await page.setViewportSize({width,height:width===1440?1024:800});
   for(const theme of ['dark','light']) {
    const toggle=page.getByRole('switch',{name:'Modo claro'});
    if((await toggle.getAttribute('aria-checked')==='true') !== (theme==='light')) await toggle.click();
    const geometry=await page.evaluate(()=>Object.fromEntries(['.devlinks','.profile','.profile__avatar','.theme-toggle','.theme-toggle__handle img','.link-button','.social-links img','.footer'].map(s=>{const e=document.querySelector(s),r=e.getBoundingClientRect(),c=getComputedStyle(e); return [s,{x:r.x,y:r.y,width:r.width,height:r.height,font:c.fontFamily,fontSize:c.fontSize,lineHeight:c.lineHeight}]})));
    if(geometry['.profile__avatar'].width!==112 || geometry['.theme-toggle'].width!==64 || geometry['.link-button'].height!==56 || geometry['.link-button'].width!==(width===1440?540:312)) throw new Error('Geometry mismatch');
    await page.getByRole('link',{name:'Meu GitHub',exact:true}).hover();
    const hover=await page.locator('.link-button').first().evaluate(e=>getComputedStyle(e).backgroundColor);
    if(hover!==(theme==='dark'?'rgba(255, 255, 255, 0.05)':'rgba(0, 0, 0, 0.02)')) throw new Error('Hover mismatch');
    await toggle.hover();
    const ring=await page.locator('.theme-toggle__handle').evaluate(e=>getComputedStyle(e).boxShadow);
    if(!ring.includes('8px')) throw new Error('Missing toggle ring');
    results.push({width,theme,geometry,hover,ring,passed:true});
   }
  }
  return results;
 })(page);
```
